    if (this._timer) clearTimeout(this._timer);
    if (this.still()) { this.setState({ dest: id, mode: m, t: 1e9 }); return; }
    const total = this.plan(this.routeFor(id, m)).total;
    const now = () => (typeof performance !== 'undefined' ? performance.now() : Date.now());
    const t0 = now();
    this.setState({ dest: id, mode: m, t: 0 });
    const tick = () => {
      const t = now() - t0;
      this.setState({ t });
      if (t < total + 60) this._raf = requestAnimationFrame(tick);
      else this._raf = 0;
    };
